always_comb
  begin : p_miss_handlerA
    hit_validA = 0;
    hit_idA = in_req_id_iA;
    hit_dataA = in_req_data_iA;
    hit_errorA = in_req_error_iA;
    push_indexA = free_idA;
    push_initA = 0;
    push_addrA = in_req_addr_iA;
    push_idmaskA = in_req_id_iA;
    push_enableA = 0;
    in_req_ready_oA = 1;
    out_req_addr_oA = in_req_addr_iA;
    out_req_id_oA = free_idA;
    out_req_valid_oA = 0;
    if (in_req_valid_iA)
      begin
        if (|(miss_in_flight_qA&in_req_id_iA))
          begin
            in_req_ready_oA = 0;
          end
        else
          if (in_req_hit_iA)
            begin
              hit_validA = 1;
              in_req_ready_oA = hit_readyA;
            end
          else
            if (pendingA&&!(write_valid_oA&&!write_ready_iA))
              begin
                push_indexA = pending_idA;
                push_enableA = 1;
              end
            else
              if (freeA)
                begin
                  out_req_addr_oA = in_req_addr_iA;
                  out_req_id_oA = free_idA;
                  out_req_valid_oA = 1;
                  in_req_ready_oA = out_req_ready_iA;
                  push_indexA = free_idA;
                  push_initA = 1;
                  push_enableA = out_req_ready_iA;
                end
              else
                begin
                  in_req_ready_oA = 0;
                end
      end

  end

