if (CFG.L1_PLRU)
  begin : gen_plru
    logic [CFG.LINE_COUNT - 1:0] [CFG.SET_COUNT - 1:0] used_masksA;
    logic [CFG.LINE_COUNT - 1:0] [CFG.SET_COUNT - 1:0] used_masksB;
    logic [CFG.LINE_COUNT - 1:0] [CFG.SET_COUNT - 1:0] used_masksC;
    logic [CFG.LINE_COUNT - 1:0] [CFG.SET_COUNT - 1:0] evict_masksA;
    logic [CFG.LINE_COUNT - 1:0] [CFG.SET_COUNT - 1:0] evict_masksB;
    logic [CFG.LINE_COUNT - 1:0] [CFG.SET_COUNT - 1:0] evict_masksC;

    always_comb
      begin
        used_masksA = '0;
        if (in_req_valid_iA&&in_req_hit_iA)
          begin
            used_masksA[in_req_addr_iA>>CFG.LINE_ALIGN][in_req_set_iA] = 1'b1;
          end
        else
          if (write_valid_oA)
            begin
              used_masksA[write_addr_oA][write_set_oA] = 1'b1;
            end

      end

    always_comb
      begin
        used_masksB = '0;
        if (in_req_valid_iB&&in_req_hit_iB)
          begin
            used_masksB[in_req_addr_iB>>CFG.LINE_ALIGN][in_req_set_iB] = 1'b1;
          end
        else
          if (write_valid_oB)
            begin
              used_masksB[write_addr_oB][write_set_oB] = 1'b1;
            end

      end

    always_comb
      begin
        used_masksC = '0;
        if (in_req_valid_iC&&in_req_hit_iC)
          begin
            used_masksC[in_req_addr_iC>>CFG.LINE_ALIGN][in_req_set_iC] = 1'b1;
          end
        else
          if (write_valid_oC)
            begin
              used_masksC[write_addr_oC][write_set_oC] = 1'b1;
            end

      end
    for(genvar i = 0; i<CFG.LINE_COUNT; i++)
          begin : gen_plru_tree

        plru_tree #(.ENTRIES(CFG.SET_COUNT)) i_plru_treeA (
            .clk_i(clk_iA),
            .rst_ni(rst_niA),
            .used_i(used_masksA[i]),
            .plru_o(evict_masksA[i])
          );

        plru_tree #(.ENTRIES(CFG.SET_COUNT)) i_plru_treeB (
            .clk_i(clk_iB),
            .rst_ni(rst_niB),
            .used_i(used_masksB[i]),
            .plru_o(evict_masksB[i])
          );

        plru_tree #(.ENTRIES(CFG.SET_COUNT)) i_plru_treeC (
            .clk_i(clk_iC),
            .rst_ni(rst_niC),
            .used_i(used_masksC[i]),
            .plru_o(evict_masksC[i])
          );
      end

    onehot_to_bin #(.ONEHOT_WIDTH(CFG.SET_COUNT)) i_evict_mask_to_indexA (
        .onehot(evict_masksA[write_addr_oA]),
        .bin(evict_indexA)
      );

    onehot_to_bin #(.ONEHOT_WIDTH(CFG.SET_COUNT)) i_evict_mask_to_indexB (
        .onehot(evict_masksB[write_addr_oB]),
        .bin(evict_indexB)
      );

    onehot_to_bin #(.ONEHOT_WIDTH(CFG.SET_COUNT)) i_evict_mask_to_indexC (
        .onehot(evict_masksC[write_addr_oC]),
        .bin(evict_indexC)
      );
  end

else
  begin : gen_lfsr

    snitch_icache_lfsr #(.N(CFG.SET_ALIGN)) i_evict_lfsrA (
        .clk_i(clk_iA),
        .rst_ni(rst_niA),
        .value_o(evict_indexA),
        .enable_i(evict_enableA)
      );

    snitch_icache_lfsr #(.N(CFG.SET_ALIGN)) i_evict_lfsrB (
        .clk_i(clk_iB),
        .rst_ni(rst_niB),
        .value_o(evict_indexB),
        .enable_i(evict_enableB)
      );

    snitch_icache_lfsr #(.N(CFG.SET_ALIGN)) i_evict_lfsrC (
        .clk_i(clk_iC),
        .rst_ni(rst_niC),
        .value_o(evict_indexC),
        .enable_i(evict_enableC)
      );
  end
