always_comb
  begin : p_response_handlerA
    pop_indexA = out_rsp_id_iA;
    pop_enableA = 0;
    write_addr_oA = pop_addrA[CFG.LINE_ALIGN+:CFG.COUNT_ALIGN];
    write_set_oA = evict_indexA;
    write_data_oA = out_rsp_data_iA;
    write_tag_oA = pop_addrA[CFG.FETCH_AW - 1:CFG.LINE_ALIGN + CFG.COUNT_ALIGN];
    write_error_oA = out_rsp_error_iA;
    write_valid_oA = 0;
    in_rsp_data_oA = out_rsp_data_iA;
    in_rsp_error_oA = out_rsp_error_iA;
    in_rsp_id_oA = pop_idmaskA;
    in_rsp_valid_oA = 0;
    hit_readyA = 1;
    out_rsp_ready_oA = 1;
    evict_enableA = 0;
    rsp_validA = 0;
    rsp_readyA = 1;
    arb_dA = arb_qA;
    if (!arb_qA.lock)
      begin
        if (hit_validA)
          begin
            arb_dA.sel = 0;
            arb_dA.lock = 1;
          end
        else
          if (out_rsp_valid_iA)
            begin
              arb_dA.sel = 1;
              arb_dA.lock = 1;
            end
          else
            begin
              arb_dA.sel = 0;
              arb_dA.lock = 0;
            end
      end

    if (arb_dA.sel==0)
      begin
        if (hit_validA)
          begin
            out_rsp_ready_oA = 0;
            in_rsp_data_oA = hit_dataA;
            in_rsp_error_oA = 0;
            in_rsp_id_oA = hit_idA;
            in_rsp_valid_oA = 1;
            hit_readyA = in_rsp_ready_iA;
          end
        else
          hit_readyA = 1;
        if (hit_readyA)
          arb_dA.lock = 0;

      end
    else
      if (arb_dA.sel==1)
        begin
          if (out_rsp_valid_iA)
            begin
              hit_readyA = 0;
              rsp_validA = 1;
              rsp_readyA =  (in_rsp_ready_iA||in_rsp_served_qA) && (write_ready_iA||write_served_qA) ;
              write_valid_oA = 1&&~write_served_qA;
              in_rsp_valid_oA = |pop_idmaskA;
              pop_enableA = rsp_readyA;
              out_rsp_ready_oA = rsp_readyA;
              evict_enableA = rsp_readyA;
            end
          else
            rsp_readyA = 1;
          if (rsp_readyA)
            arb_dA.lock = 0;

        end

  end

