logic in_rsp_served_nextB;
logic in_rsp_served_nextC;
assign write_served_nextA = rsp_validA&~rsp_readyA& (write_served_qA|write_ready_iA) ;
assign write_served_nextB = rsp_validB&~rsp_readyB& (write_served_qB|write_ready_iB) ;
assign write_served_nextC = rsp_validC&~rsp_readyC& (write_served_qC|write_ready_iC) ;
assign in_rsp_served_nextA = rsp_validA&~rsp_readyA& (in_rsp_served_qA|in_rsp_ready_iA) ;
assign in_rsp_served_nextB = rsp_validB&~rsp_readyB& (in_rsp_served_qB|in_rsp_ready_iB) ;
assign in_rsp_served_nextC = rsp_validC&~rsp_readyC& (in_rsp_served_qC|in_rsp_ready_iC) ;

